fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Ensure both input arrays have the same length
    assert!(
        arr1.len() == arr2.len(),
        "Input arrays must have the same length"
    );

    // Compute element-wise division
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| {
            // Since we assume b != 0 and (a / b) fits within i32::MAX,
            // the u32 division here cannot overflow or panic.
            a / b
        })
        .collect()
}

